/**
 * Build and verify the four Android APKs (standalone/launcher, debug/release).
 *
 *   npm run android:build [-- --allow-unpackaged-runtime]
 *   npm run android:build -- --test-mocks
 *
 * Inputs are checked first (scripts/android-build-preflight.mjs): the pinned
 * checkout, the staged on-device voice outputs, the prepared runtime source and, for
 * distribution builds, the staged resident runtime. `npm run android:build:local`
 * prepares and stages the runtime before calling this script. The Gradle host is
 * generated by the pinned upstream consumer-host generator from
 * android/consumer-host.json (scripts/android-host.mjs) before Gradle runs.
 *
 * Distribution builds (the default) are always flag-off: ELIZA_DEV_ALLOW_TEST_MOCKS
 * and its VITE_ mirror are removed from every child environment, whatever the
 * caller exported, and Gradle receives -PELIZA_DEV_ALLOW_TEST_MOCKS=0. Outputs go
 * to artifacts/.
 * --test-mocks builds the web bundle and APKs with the flag on and writes only
 * under artifacts/test-mocks/; it never replaces distribution artifacts.
 * Afterwards (also on failure) it rebuilds and syncs the flag-off bundle, so
 * web-dist and the Android web assets never stay flag-on.
 * --allow-unpackaged-runtime is a developer option forwarded to verify-apks:
 * releases without the staged resident runtime are recorded distributable:false
 * instead of failing the build.
 */
import { execFileSync, spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const FLAG = "ELIZA_DEV_ALLOW_TEST_MOCKS";
const FLAG_ENV_NAMES = [FLAG, `VITE_${FLAG}`, `ORG_GRADLE_PROJECT_${FLAG}`];
/**
 * The release-signing environment names the generated Gradle host reads
 * (android/consumer-host.json, profile.signing): store file, store password,
 * key alias and key password. Only names are recorded; the human signer
 * supplies the values when building a release.
 */
export const SIGNING_ENV = (() => {
  const signing = JSON.parse(fs.readFileSync(new URL("../android/consumer-host.json", import.meta.url), "utf8")).profile.signing;
  const names = ["storeFile", "storePassword", "keyAlias", "keyPassword"].map(key => signing?.[key]);
  if (names.some(name => !/^[A-Z][A-Z0-9_]*$/.test(name ?? "")) || new Set(names).size !== 4)
    throw new Error("android/consumer-host.json must name four release-signing environment variables");
  return Object.freeze(names);
})();
const USAGE = "Usage: npm run android:build -- [--test-mocks] [--allow-unpackaged-runtime] [--skip-instrumentation]";

export function parseBuildArgs(argv) {
  const options = { testMocks: false, allowUnpackagedRuntime: false, skipInstrumentation: false };
  for (const arg of argv) {
    if (arg === "--test-mocks") options.testMocks = true;
    else if (arg === "--runtime-profile=cloud") options.runtimeProfile = "cloud";
    else if (arg === "--skip-instrumentation") options.skipInstrumentation = true;
    else if (arg === "--allow-unpackaged-runtime") options.allowUnpackagedRuntime = true;
    else throw new Error(`Unknown option ${arg}. ${USAGE}`);
  }
  if (options.runtimeProfile === "cloud" && (options.testMocks || options.allowUnpackagedRuntime)) throw Error("Cloud profile requires a genuine packaged resident and test mocks off");
  if (options.testMocks && options.skipInstrumentation) throw new Error("Test-mocks builds require instrumentation APKs");
  return options;
}

/** Child environment for a build: the flag is set only for --test-mocks. */
export function buildEnv(base, { testMocks, runtimeProfile = "native" }) {
  const env = { ...base };
  for (const name of FLAG_ENV_NAMES) delete env[name];
  env.VITE_ELIZA_RUNTIME_PROFILE = runtimeProfile;
  if (testMocks) {
    env[FLAG] = "1";
    env[`VITE_${FLAG}`] = "1";
  }
  return env;
}

export function gradleFlagArgs({ testMocks, allowUnpackagedRuntime = false, runtimeProfile = "native" }) {
  return [...(runtimeProfile === "cloud" ? ["-PELIZA_RUNTIME_PROFILE=cloud"] : []),`-P${FLAG}=${testMocks ? "1" : "0"}`, `-PELIZA_ALLOW_UNPACKAGED_RUNTIME=${allowUnpackagedRuntime ? "1" : "0"}`];
}

export const outputDirectory = ({ testMocks }) => (testMocks ? "artifacts/test-mocks" : "artifacts");

/**
 * A test-mocks build has to sync a flag-on bundle into web-dist and the Android
 * assets. Afterwards, whether it succeeded or failed, rebuild and sync the
 * flag-off bundle so neither web-dist nor android/app/src/main/assets/public is
 * left carrying mocks for a later sync, Gradle or archive step.
 */
export function withDistributionWebRestored(options, baseEnv, run, body, { root = process.cwd() } = {}) {
  if (!options.testMocks) return body();
  let failed = false;
  try {
    return body();
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    try {
      run("npm", ["run", "android:sync"], { env: buildEnv(baseEnv, { testMocks: false }) });
      const flags = JSON.parse(fs.readFileSync(path.join(root, "web-dist/build-flags.json"), "utf8"));
      if (flags.testMocks !== false) throw new Error("web-dist/build-flags.json still records testMocks after restoring the distribution bundle");
      console.log("Restored the flag-off web bundle in web-dist and the Android assets.");
    } catch (error) {
      // Never hide the original failure; still report that web-dist may carry mocks.
      if (!failed) throw error;
      console.error(`Could not restore the flag-off web bundle: ${error.message}`);
    }
  }
}
const signingValue = (env, name) => typeof env[name] === "string" && env[name].trim() !== "";
export const signingRequested = env => SIGNING_ENV.every(name => signingValue(env, name));

/** Names (never values) of the signing variables a partial ELIZAOS_* set lacks; null when none or all are set. */
export function partialSigningProblem(env) {
  const missing = SIGNING_ENV.filter(name => !signingValue(env, name));
  if (missing.length === 0 || missing.length === SIGNING_ENV.length) return null;
  return `Incomplete release signing environment: missing ${missing.join(", ")}. Set all of ${SIGNING_ENV.join(", ")} or none.`;
}

export const RELEASE_SIGNER_FILE = "android/release-signer.json";
const hex64 = /^[0-9a-f]{64}$/;

/** Validate the committed release-signer descriptor. */
export function validateReleaseSigner(descriptor) {
  const problems = [];
  if (!descriptor || descriptor.schema !== 1) problems.push("schema must be 1");
  const signer = descriptor?.signerSha256;
  if (signer !== "unset" && !(typeof signer === "string" && hex64.test(signer)))
    problems.push("signerSha256 must be 'unset' or a lowercase 64-hex certificate digest");
  const last = descriptor?.lastRelease;
  if (!last || typeof last !== "object") problems.push("lastRelease is required");
  else if (last.versionCode !== null && !(Number.isInteger(last.versionCode) && last.versionCode > 0))
    problems.push("lastRelease.versionCode must be null or a positive integer");
  if (problems.length) throw new Error(`${RELEASE_SIGNER_FILE} is invalid: ${problems.join("; ")}`);
  return descriptor;
}

export function readReleaseSigner(root = process.cwd()) {
  return validateReleaseSigner(JSON.parse(fs.readFileSync(path.join(root, RELEASE_SIGNER_FILE), "utf8")));
}

/**
 * Release admission against the descriptor. `failures` stop verification (a signed
 * release with a different certificate or a non-advancing versionCode); `blockers`
 * keep an otherwise valid release distributable:false (unsigned, signer unset,
 * an unsigned build that does not advance the recorded versionCode).
 */
export function releaseAdmission({ signed, signerSha256, versionCode }, descriptor) {
  validateReleaseSigner(descriptor);
  const failures = [];
  const blockers = [];
  if (!signed) blockers.push("unsigned release");
  if (descriptor.signerSha256 === "unset") blockers.push(`release signer is unset in ${RELEASE_SIGNER_FILE}`);
  else if (signed && signerSha256 !== descriptor.signerSha256)
    failures.push(`release signer ${signerSha256 ?? "unknown"} does not match ${RELEASE_SIGNER_FILE} ${descriptor.signerSha256}`);
  const last = descriptor.lastRelease.versionCode;
  if (last !== null && !(Number.isInteger(versionCode) && versionCode > last)) {
    const message = `versionCode ${versionCode} is not greater than the last recorded release ${last}`;
    (signed ? failures : blockers).push(message);
  }
  return { failures, blockers, signerMatches: signed && descriptor.signerSha256 !== "unset" && signerSha256 === descriptor.signerSha256 };
}

/**
 * The SBOM written beside distribution APKs: the source pins, the APKs verify-apks just
 * recorded and, when a resident runtime is staged, that payload. Offline; it lists what was
 * built and never changes a distributable verdict.
 */
export function sbomArgs(outDir, root = process.cwd()) {
  const staged = fs.existsSync(path.join(root, "android/app/src/main/assets/agent/agent-bundle.js"));
  return ["--out", path.join(outDir, "sbom", "alphaphone.cdx.json"), "--apks", outDir, ...(staged ? ["--packaged-runtime"] : [])];
}

async function main() {
  const options = parseBuildArgs(process.argv.slice(2));
  // A partial signing set would silently produce unsigned releases; refuse it up front.
  const partial = partialSigningProblem(process.env);
  if (partial) throw new Error(partial);
  // Report missing inputs (pinned checkout, speech AAR, prepared/staged runtime)
  // with the exact command to run, before web sync and a long Gradle build.
  const preflight = spawnSync(process.execPath, [path.join(import.meta.dirname, "android-build-preflight.mjs"), ...process.argv.slice(2).filter(arg => arg !== "--skip-instrumentation")], { stdio: "inherit" });
  if (preflight.status !== 0) process.exit(preflight.status ?? 1);
  // A malformed release-signer descriptor fails before the long build, not after it.
  readReleaseSigner();
  // The toolchain resolver and the build orchestration live in the pinned checkout, which the preflight verified.
  const { androidEnv } = await import("./toolchain.mjs");
  const { buildAndroidConsumer } = await import("../vendor/eliza/packages/app/scripts/mobile/android/build-consumer.mjs");
  const baseEnv = androidEnv();
  const run = (cmd, args, extra = {}) =>
    execFileSync(cmd, args, { stdio: "inherit", env: buildEnv(baseEnv, options), ...extra });
  withDistributionWebRestored(options, baseEnv, run, () => build(options, baseEnv, run, buildAndroidConsumer));
}

/**
 * What the upstream consumer build receives for one Alpha build. Upstream owns the Gradle
 * invocation and artifact collection: the four distribution APKs (signed releases keep
 * `<variant>-release.apk`), instrumentation APKs, R8 mappings and the optional sequential
 * low-disk mode (ALPHA_ANDROID_LOW_DISK=1). Alpha supplies the flags, output directory,
 * signing variable names, build record and its own APK verification.
 */
export function consumerBuildOptions(options, env, root) {
  return {
    root,
    environment: env,
    variants: ["standalone", "launcher"],
    project: "android",
    output: outputDirectory(options),
    gradleArguments: gradleFlagArgs(options),
    androidTest: !options.skipInstrumentation,
    // Distribution instrumentation APKs live in a subdirectory so artifacts/*.apk stays the four
    // distribution APKs (scripts/android-instrumentation.mjs); test-mocks keeps them beside its APKs.
    androidTestOutput: options.testMocks ? "" : "instrumentation",
    lint: !options.testMocks,
    signing: { environment: [...SIGNING_ENV] },
    mappings: true,
    // Opt-in for constrained builders; retained APKs and source evidence are never cleaned.
    sequential: env.ALPHA_ANDROID_LOW_DISK === "1",
    // verify-apks compares this record with the APKs it verifies. Upstream writes it only after
    // every APK of this build is in place, so a failed build keeps the previous APKs and record.
    record: {
      name: "build-config.json",
      metadata: {
        createdAt: new Date().toISOString(),
        testMocks: options.testMocks,
        runtimeProfile: options.runtimeProfile || "native",
        mapsConfigured: Boolean(env.VITE_MAPS_BASE_URL),
        signingRequested: signingRequested(env),
        versionOverride: { code: env.ELIZAOS_VERSION_CODE ?? null, name: env.ELIZAOS_VERSION_NAME ?? null },
      },
    },
    verify: { command: "node", args: ["scripts/verify-apks.mjs",
      ...(options.testMocks ? ["--test-mocks"] : []),
      ...(options.allowUnpackagedRuntime ? ["--allow-unpackaged-runtime"] : []),
      ...(options.runtimeProfile === "cloud" ? ["--runtime-profile=cloud"] : [])] },
    archive: null,
  };
}

function build(options, baseEnv, run, buildAndroidConsumer) {
  const env = buildEnv(baseEnv, options);
  const outDir = outputDirectory(options);
  console.log(`Android build: ${options.testMocks ? "TEST-MOCKS (never distributable) -> " : "distribution, test mocks off -> "}${outDir}/`);

  run("node", ["scripts/verify-upstream.mjs"]);
  // The pinned upstream generator writes the Gradle host from android/consumer-host.json.
  run("node", ["scripts/android-host.mjs"]);
  run("npm", ["run", "android:sync"]);
  // The packaged web bundle must carry the requested flag before Gradle runs.
  const flagsFile = "web-dist/build-flags.json";
  if (fs.existsSync(flagsFile)) {
    const flags = JSON.parse(fs.readFileSync(flagsFile, "utf8"));
    if ((flags.runtimeProfile || "native") !== (options.runtimeProfile || "native")) throw Error("Web runtime profile differs from Android profile");
    if (flags.testMocks !== options.testMocks)
      throw new Error(`${flagsFile} records testMocks=${flags.testMocks}; expected ${options.testMocks}`);
  }

  const root = fs.realpathSync(path.resolve(import.meta.dirname, ".."));
  buildAndroidConsumer(consumerBuildOptions(options, env, root));
  if (options.testMocks)
    console.log("Test-mocks APKs are for mock-isolation instrumentation only and are never distributable.");
  else run("node", ["scripts/generate-sbom.mjs", ...sbomArgs(outDir, root)]);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
